        if(sp.type==='tee'&&!sp.vert){ // té d'attente posé à la main : conduite proche = côté de la branche (té droit) ; conduite lointaine = té à saut, côte à côte
          const q=ptAt(pts,sp.m);const s=sp.side||1;const nx=-Math.sin(q.th)*s,ny=Math.cos(q.th)*s;const q1=[q.x+nx,q.y+ny];const near=projOnPoly(cps.A,q1).d<=projOnPoly(cps.R,q1).d?'A':'R';
          const pr=projOnPoly(cp,[q.x,q.y]);return {...sp,m:pr.m,teeType:c!==near?(sautType()||sp.teeType):sp.teeType,far:c!==near};}
