    if((l.endType||'kit')==='bypass'&&conds.A&&conds.R){const uA=conds.A.pieces.find(p=>p.kind==='bypassEnd'),uR=conds.R.pieces.find(p=>p.kind==='bypassEnd');if(uA&&uR&&uA.apex){conds.A.welds.push({i:-1,m:conds.A.length,x:uA.apex[0],y:uA.apex[1],between:[uA.id,uR.id+' (retour)'],dev:0,fc:false,dn,bypass:true});
      const note=`by-pass en bout de ligne : 2 coudes 90° recoupés + soudure entre eux, à l'entraxe ${fmt(e)} m — les jambes pré-isolées (mini ${fmt(rules.jambeMin)} m) ne rentrent pas dans ${fmt(e/2)} m : à réaliser en coudes acier nus isolés sur place ou en élargissant l'entraxe (à cadrer)`;conds.A.notes.push({kind:'doubt',m:conds.A.length,txt:note});}}
