      if(p.kind==='endcap'){const b=p.path[p.path.length-1],b2=p.path[p.path.length-2]||p.path[0];const th=Math.atan2(b[1]-b2[1],b[0]-b2[0]);const nx=-Math.sin(th),ny=Math.cos(th);const hw=p.casing*.9*ws;const cx=p.sub==='provisoire'?'#b8560f':'#333';h+=`<path d="M${b[0]+nx*hw} ${b[1]+ny*hw}L${b[0]-nx*hw} ${b[1]-ny*hw}" stroke="${cx}" stroke-width="${Math.max(p.casing*.35*ws,2.5/k)}"/>`;if(p.sub==='provisoire')h+=`<path d="M${b[0]+nx*hw} ${b[1]+ny*hw}L${b[0]-nx*hw} ${b[1]-ny*hw}" stroke="#fff" stroke-width="${Math.max(p.casing*.12*ws,1/k)}" stroke-dasharray="${Math.max(0.15,3/k)} ${Math.max(0.1,2/k)}"/>`;}
      if(k>=4&&p.path.length>=2&&!nue&&p.kind!=='bypassEnd'){const be=cat.bareEnds(p.dn);const a=p.path[0],a2=p.path[1],b=p.path[p.path.length-1],b2=p.path[p.path.length-2];const th1=Math.atan2(a2[1]-a[1],a2[0]-a[0]),th2=Math.atan2(b[1]-b2[1],b[0]-b2[0]);const od=cat.od(p.dn);bare.push(`<path d="M${a[0]} ${a[1]}L${a[0]+Math.cos(th1)*be} ${a[1]+Math.sin(th1)*be}M${b[0]} ${b[1]}L${b[0]-Math.cos(th2)*be} ${b[1]-Math.sin(th2)*be}" stroke="#f4f3ee" stroke-width="${p.casing*.7*ws}"/><path d="M${a[0]} ${a[1]}L${a[0]+Math.cos(th1)*be} ${a[1]+Math.sin(th1)*be}M${b[0]} ${b[1]}L${b[0]-Math.cos(th2)*be} ${b[1]-Math.sin(th2)*be}" stroke="#333" stroke-width="${od*ws}"/>`);}
