    if(k>=6){cd.welds.forEach(w=>{const p=cd.pieces[w.i];const q=cd.pieces[w.i+1];if(!p||!q||w.bypass)return;const jl=cat.joint(w.dn||cd.dn).L,cw=cat.casing(w.dn||cd.dn);const th=Math.atan2((q.path[1]?q.path[1][1]:w.y)-w.y,(q.path[1]?q.path[1][0]:w.x)-w.x);h+=`<g transform="translate(${w.x} ${w.y}) rotate(${th*180/Math.PI})"><rect x="${-jl/2}" y="${-cw*.62*ws}" width="${jl}" height="${cw*1.24*ws}" fill="#e6e3da" stroke="#8f8c86" stroke-width="${1/k}" opacity=".95" rx="${cw*.15*ws}"/></g>`;});}
