        const svg=`<svg width="${W}" height="${H}" style="background:#f4f3ee;border-radius:6px"><line x1="0" y1="${z0}" x2="${W}" y2="${z0}" stroke="${dp.top==='A'?'#2a5fb4':'#c8382f'}" stroke-width="4"/><polyline points="${X(dp.m0-Lt/2-3)},${z0-6} ${X(dp.m0-Lt/2)},${z0-6} ${X(dp.m0+Lt/2)},${z1} ${X(dp.m1-Lt/2)},${z1} ${X(dp.m1+Lt/2)},${z0-6} ${X(dp.m1+Lt/2+3)},${z0-6}" fill="none" stroke="${dp.top==='A'?'#c8382f':'#2a5fb4'}" stroke-width="4"/><text x="${X(dp.m0)}" y="12" font-size="10" text-anchor="middle" fill="#52514e">PK ${fmt(dp.m0)} · 2 × ${A}°</text><text x="${X(dp.m1)}" y="12" font-size="10" text-anchor="middle" fill="#52514e">PK ${fmt(dp.m1)} · 2 × ${A}°</text><text x="${W-4}" y="${z1-4}" font-size="9" text-anchor="end" fill="#52514e">+${fmt(e)} m</text></svg>`;
