let bgRaf=0;function renderBgIfNeeded(){const b=state.bg;if(!b||!b.drawing||b.show===false)return;const k=state.view.k;const zoomed=k>=2&&b.drawing.length>300;const key=zoomed?`${Math.round(k*100)}:${Math.round(state.view.tx)}:${Math.round(state.view.ty)}`:'full';if(b._lastKey===key)return;if(bgRaf)cancelAnimationFrame(bgRaf);bgRaf=requestAnimationFrame(()=>{bgRaf=0;renderBg();});}
function saveBg(){try{const b=state.bg;if(!b||!b.image){localStorage.removeItem('trace:bg:v1');return;}localStorage.setItem('trace:bg:v1',JSON.stringify({image:b.image,opacity:b.opacity,show:b.show,name:b.name}));}catch(e){flash('Image trop lourde pour être gardée après rechargement (elle reste dans le chantier enregistré)');}}
function loadBg(){try{const s=JSON.parse(localStorage.getItem('trace:bg:v1')||'null');if(!s||!s.image)return;const b=bgObj();b.image=s.image;b.opacity=s.opacity;b.show=s.show;b.name=s.name||'';b.bbox=[s.image.x,s.image.y,s.image.x+s.image.w,s.image.y+s.image.h];}catch(e){}}
async function loadBgImage(file){const src=await shrinkImage(file,2200);const dims=await new Promise((res,rej)=>{const im=new Image();im.onload=()=>res({pw:im.width,ph:im.height});im.onerror=rej;im.src=src;});
  // taille de départ : l'image couvre l'écran courant (on règle ensuite l'échelle avec deux points)
  const v=state.view;const W=svg.clientWidth,H=svg.clientHeight;const wx0=(-v.tx)/v.k,wy0=(-v.ty)/v.k;const wW=W/v.k;const w=wW*.9,h=w*dims.ph/dims.pw;const b=bgObj();b.image={src,pw:dims.pw,ph:dims.ph,x:wx0+wW*.05,y:wy0+(H/v.k-h)/2,w,h};b.name=file.name;b.bbox=[b.image.x,b.image.y,b.image.x+w,b.image.y+h];renderBg();saveBg();
  flash('Image chargée — règle l\'échelle : « 📏 Échelle », deux points du plan puis la distance réelle');setMode('scale');}
function applyScale(p1,p2){const b=state.bg;if(!b||!b.image)return;const d=Math.hypot(p2[0]-p1[0],p2[1]-p1[1]);if(d<1e-6)return;const txt=prompt('Distance réelle entre les deux points (m) :');const D=parseFloat(String(txt||'').replace(',','.'));if(!(D>0))return;const f=D/d;const im=b.image;im.x=p1[0]-(p1[0]-im.x)*f;im.y=p1[1]-(p1[1]-im.y)*f;im.w*=f;im.h*=f;b.bbox=[im.x,im.y,im.x+im.w,im.y+im.h];renderBg();saveBg();flash(`Échelle réglée : ${fmt(1/f>0?im.w/im.pw*1000:0)} mm par pixel — ${fmt(D)} m entre les deux points`);setMode('select');}
$('#bgImg').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{await loadBgImage(f);}catch(err){alert('Image illisible : '+(err.message||err));}e.target.value='';});
$('#bgOp').addEventListener('input',e=>{bgObj().opacity=(+e.target.value)/100;renderBg();saveBg();});$('#bgShow').addEventListener('change',e=>{bgObj().show=e.target.checked;renderBg();saveBg();});
$('#bgScale').onclick=()=>setMode(state.mode==='scale'?'select':'scale');$('#bgMove').onclick=()=>setMode(state.mode==='moveBg'?'select':'moveBg');
